    trace_id: chunk.trace_id,
    pii_count: chunk.pii_count,
    created_at: chunk.created_at
  };

  // Apply contextual header
  originalChunk.contextual_header = contextualHeader;
  originalChunk.contextual_content = contextualHeader
    ? `${contextualHeader}\n\n${originalChunk.content}`
    : originalChunk.content;
  originalChunk.contextual_prefix = contextualHeader;
  originalChunk.contextual_retrieval_applied = !!contextualHeader;

  enrichedChunks.push(originalChunk);

  if (!parentData && chunk._parent_data) {
    parentData = chunk._parent_data;
  }
}

const successCount = enrichedChunks.filter(c => c.contextual_retrieval_applied).length;

return {
  chunks: enrichedChunks,
  parent_id: parentData?.parent_id,
  parent_filename: parentData?.parent_filename,
  document_title: parentData?.document_title,
  total_chunks: enrichedChunks.length,
  trace_id: parentData?.trace_id,
  tenant_id: parentData?.tenant_id,
  lock_key: parentData?.lock_key,
  lock_value: parentData?.lock_value,
  contextual_retrieval_stats: {
    total: enrichedChunks.length,
    success: successCount,
    failed: enrichedChunks.length - successCount
  }
};

// PATCH P02: BM25 Sparse Vector Generator for Pinecone Hybrid Search
// Impact: +30-50% recall combined with dense embeddings
// Uses client-side BM25 scoring with hashed sparse vectors

const chunks = $json.chunks || [];

// === BM25 PARAMETERS ===
const K1 = 1.2;
const B = 0.75;

// === Tokenizer (FR+EN) ===
const STOP_WORDS = new Set([
  'le', 'la', 'les', 'un', 'une', 'des', 'de', 'du', 'au', 'aux',
  'et', 'ou', 'mais', 'donc', 'car', 'ni', 'que', 'qui', 'quoi',
  'ce', 'cette', 'ces', 'mon', 'ton', 'son', 'ma', 'ta', 'sa',
  'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to',
  'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be',
  'it', 'this', 'that', 'these', 'those', 'i', 'you', 'he', 'she',
  'nous', 'vous', 'ils', 'elles', 'je', 'tu', 'il', 'elle',
  'est', 'sont', 'a', 'ont', 'pas', 'ne', 'plus', 'comme'
]);

function tokenize(text) {
  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length > 2 && !STOP_WORDS.has(t));
}

function hashToken(token) {
  let hash = 0;
  for (let i = 0; i < token.length; i++) {
    const char = token.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash) % 100000;
}

// === Document Frequencies ===
const allTokenSets = chunks.map(chunk => {
  const text = chunk.contextual_content || chunk.content;
  return new Set(tokenize(text));
});

const df = {};
for (const tokenSet of allTokenSets) {
  for (const token of tokenSet) {
    df[token] = (df[token] || 0) + 1;
  }
}

const N = chunks.length;
const avgDl = chunks.reduce((sum, c) => {
  return sum + tokenize(c.contextual_content || c.content).length;
}, 0) / Math.max(N, 1);

// === BM25 Sparse Vectors ===
const sparseVectors = chunks.map((chunk) => {
  const text = chunk.contextual_content || chunk.content;
  const tokens = tokenize(text);
  const dl = tokens.length;

  const tf = {};
  for (const token of tokens) {
    tf[token] = (tf[token] || 0) + 1;
  }

  const indices = [];
  const values = [];

  for (const [term, freq] of Object.entries(tf)) {
    const idf = Math.log((N - (df[term] || 0) + 0.5) / ((df[term] || 0) + 0.5) + 1);
    const tfNorm = (freq * (K1 + 1)) / (freq + K1 * (1 - B + B * (dl / avgDl)));
    const score = idf * tfNorm;

    if (score > 0) {
      indices.push(hashToken(term));
      values.push(Math.round(score * 1000) / 1000);
    }
  }

  return { indices, values };
});

const enrichedChunks = chunks.map((chunk, idx) => ({
  ...chunk,
  sparse_values: sparseVectors[idx],
  bm25_token_count: tokenize(chunk.contextual_content || chunk.content).length
}));

return {
  ...$json,
  chunks: enrichedChunks,
  bm25_stats: {
    vocabulary_size: Object.keys(df).length,
    avg_doc_length: Math.round(avgDl),
    total_chunks: N
  }
};
